INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tender Loving Care', 'You are about to enter a fantasy quite unlike anything you''ve ever seen or felt before - a fantasy built from the stuff of your very own mind. Tender Loving Care is not just a finely crafted suspense story; it''s an exploration into your innermost perceptions, opinions, and attitudes. The unfolding story is shaped and changed by your responses to it, so that no two people will experience Tender Loving Care in exactly the same way.' FROM games WHERE igdb_id = 29439 ON CONFLICT (game_id, language_code) DO NOTHING;
