INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('kagero-deception-ii', 4124, '1998-07-23', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/coabtc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4260.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kagero: Deception II', 'Kagero: Deception II is the sequel to Tecmo''s Deception. It follows a similar, hard-to-classify gameplay style, which can be perhaps defined as a real-time strategy game with RPG elements. Instead of commanding troops and units, Millennia has to place traps and activate them to prevent the intruders from conquering the castle. Unlike the first game, Kagero: Deception II is played from a third-person perspective. A major addition to the gameplay is the introduction of "trap combos": traps can be positioned in such a way that they will trigger each other, leading to powerful combinations that would harm the invaders more. The game also allows to customize traps and use various materials to build new ones. As before, the main character and her traps grow in power in correspondence with the amount of enemies killed, lending the game a RPG flavor. The morality system also present in this sequel, as the player can decide for Millennia whom to kill and whom to spare. Eventually, the player will be able to choose to join either the Timenoids or the humans.' FROM games WHERE igdb_id = 4124 ON CONFLICT (game_id, language_code) DO NOTHING;
