INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('descent-freespace-the-great-war', 669, '1998-06-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3wfe.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar4sno.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Descent: Freespace - The Great War', 'The heartless Shivans emerged through subspace near Earth, harboring technology light years ahead of anything seen before. They made no attempt to communicate. They did not respond to your heralds. They simply attacked and destroyed everything in their path. As a pilot for the Galactic Terran Alliance (GTA) you are no stranger to war. But when racing through space to engage your new enemy for the first time, you sense something different. Suddenly, darkness blankets your craft. Your stomach sinks as your eyes pan across the Shivan flagship''s massive body. Then it begins. Swarms of fighters pour from the belly of the flagship and scream towards you. You are about to discover everything you thought you knew about space combat just changed.' FROM games WHERE igdb_id = 669 ON CONFLICT (game_id, language_code) DO NOTHING;
