INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rhapsody: A Musical Adventure', 'Rhapsody: A Musical Adventure, released in Japan as The Puppet Princess of Marl Kingdom is a tactical role-playing game for the PlayStation from Atlus USA and Nippon Ichi Software, the creators of Disgaea, and is part of the Marl Kingdom series. Rhapsody, along with its sequels, are considered musical RPGs, meaning in place of FMV cutscenes, there are musical numbers, complete with vocals. The game is also known for its "overwhelming cuteness" and low level of difficulty. Although this may make the game seem geared towards a younger audience, in Japan, the game and series in general has seen much success.' FROM games WHERE igdb_id = 16997 ON CONFLICT (game_id, language_code) DO NOTHING;
