INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Astérix: The Gallic War', 'Astérix: The Gallic War is a light-hearted action-strategy hybrid game featuring the popular Asterix comic book characters. You play as Asterix, Obelix and the rest of the Celtic Gaul army as they war with the Romans, led by Caesar, who have seized all but one territory from the Gaul Empire. After gathering your army, you must capture lands adjacent to yours.' FROM games WHERE igdb_id = 45232 ON CONFLICT (game_id, language_code) DO NOTHING;
