INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The House of the Dead 2', 'The House of the Dead 2 is a first-person light gun shooter arcade game with a horror theme and the second game in The House of the Dead series of video games. The direct sequel to The House of the Dead, it was developed by Sega for arcades on the Sega NAOMI board in November 1998 then later ported to the Dreamcast in 1999 and Microsoft Windows in 2001, and is also found on the Xbox as an unlockable bonus in The House of the Dead III. The game appears in the compilation The House of the Dead 2 & 3 Return for Wii. The Dreamcast version became a Sega All Stars title.' FROM games WHERE igdb_id = 13777 ON CONFLICT (game_id, language_code) DO NOTHING;
