INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('a2-racer-ii', 80309, '1998-12-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6hps.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scxzl2.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'A2 Racer II', 'A2 Racer II again allows you to race on the well known Dutch A-2 highway. But also race tracks have been set out through 3 major Dutch cities: Amsterdam, Rotterdam and Den Haag (the Hague). Like in the original you join illegal street races. There are six stages in the game. The first stage takes place in Amsterdam, the second on the A-2 towards Den Haag, the third in Den Haag itself, the fourth on the road to Rotterdam, the fifth in Rotterdam, and the last from Rotterdam past Utrecht back to Amsterdam. Each city has been carefully recreated in a completely new and improved 3D engine. Racing is made difficult by the police who try to block you by setting up blockades or pushing you off the road. Each time you get caught you get a ticket and lose time. With the third ticket you are out of the race. The game doesn''t have a visible damage system, but if you get into too severe a crash you are also out of the race.' FROM games WHERE igdb_id = 80309 ON CONFLICT (game_id, language_code) DO NOTHING;
