INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Putt-Putt Enters the Race', 'Putt-Putt Enters the Race is a Junior Adventure in which Putt-Putt searches for the items he needs to prepare for the Car Town 500. This point-and-click adventure game aimed at children features simple inventory puzzles as well as various minigames, including a racing minigame at the very end.' FROM games WHERE igdb_id = 3738 ON CONFLICT (game_id, language_code) DO NOTHING;
