INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Mizzurna Falls', 'Can you find your lost friend before it''s too late? Welcome to the snowy town of Mizzurna Falls. You play as Matthew, a young man who is looking for his childhood friend Emma, who has gone missing. You can explore the titular Mizzurna Falls with your car, interact with the locals and find out about the town''s dark history, but in the end, you have to solve the case before it''s too late...' FROM games WHERE igdb_id = 43839 ON CONFLICT (game_id, language_code) DO NOTHING;
