INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('brigandine-the-legend-of-forsena', 3127, '1998-04-02', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co2ywm.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar424v.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brigandine: The Legend of Forsena', 'Can you defend your lands against a great evil? As one of the five Knights of Rune, it is your duty to battle the monsters and armies of an evil emperor and restore peace to a broken land. Once you choose your character, you''ll organize your party members into attack forces and begin the battle. A deep and involving war simulation, the game''s system is based largely on hit points, experience, and levels making it an effective role-playing title as well. Brigandine: The Legend of Forsena is a rich game and a time-tested classic.' FROM games WHERE igdb_id = 3127 ON CONFLICT (game_id, language_code) DO NOTHING;
