INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('might-and-magic-vi-the-mandate-of-heaven', 790, '1998-04-30', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3czc.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arvmi.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Might and Magic VI: The Mandate of Heaven', 'The Ironfist Dynasty is tottering on the brink of ruin. As endless calamities plague the kingdom of Enroth, evil doomsday cultists plan to overthrow child Prince Nicolai and claim the throne for their charismatic leader. Fear grips the land and the people wonder if their sovereign has lost the Mandate of Heaven - the divine right to rule. The enemies of reason are at the gate and only extraordinary heroes can stem the tide of darkness. Will you answer the call? From the depths of the deepest dungeons, to the intrigues of the royal court, you will lead a band of adventurers on a dangerous journey of amazing depth and intelligence. With a completely new 3D graphics engine and a non-linear adventure system, Might and Magic VI: The Mandate of Heaven brings a unique role-playing experience to life.' FROM games WHERE igdb_id = 790 ON CONFLICT (game_id, language_code) DO NOTHING;
