INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('deep-fear', 46057, '1998-07-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co7l9l.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scnzq1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Deep Fear', 'All contact is lost with a submarine on a routine mission which then crashes into an underwater facility. The occupants of the underwater facility are ordered to board the submarine and find out what went wrong. On board the vessel, strange things are happening which are taking control of the crew. The crew are mutating due to an alien parasite and members of the search team have to figure out what is happening and how to stop it! The game is played via a third person view which is just behind the character and you look over his shoulder. The game is based underwater in a submarine so the developers have added a claustrophobic feeling by giving some areas a limited amount of air so you have to run through to activate the air circulation system. Controls are your typical Resident Evil style which is you pull the Right shoulder button to draw your gun, your d-pad to aim and then a button to shoot. Along your journey of the submarine, you will need to find objects such as keycards to unlock doors and better weapons.' FROM games WHERE igdb_id = 46057 ON CONFLICT (game_id, language_code) DO NOTHING;
