INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Star Soldier: Vanishing Earth', 'In the year 2098 mankind had been critically attacked by a military force from Zeograd, a hostile planet in a far off galaxy. Commander Parker Deehan of Special Interception Airforce (SIA) decided to deploy and pilot the F98 Star Soldier fighter craft into the front line of battle against Zeograd. Losing the battle meant the extinction of mankind and the total annihilation of Earth!' FROM games WHERE igdb_id = 3604 ON CONFLICT (game_id, language_code) DO NOTHING;
