INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fallout 2', 'A turn-based tactical Western RPG in which the Chosen One is tasked with exploring post-nuclear California to locate and retrieve the fabled Garden of Eden Creation Kit for their famine-stricken tribe, while coming into contact through branching dialogue trees with numerous tribes, factions and micro-civilizations, each with their own virtues, vices, socioeconomic situations and political agendas.' FROM games WHERE igdb_id = 14 ON CONFLICT (game_id, language_code) DO NOTHING;
