INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('rugrats-search-for-reptar', 2787, '1998-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co8tid.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/kwmbdsomvhiamlfzezot.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rugrats: Search for Reptar', 'Rugrats: Search for Reptar is the first video game based off of the popular Nickelodean television series. The game follows the main character of the cartoon Rugrats, Tommy Pickles, who has lost eleven pieces of a twelve-piece jigsaw puzzle featuring the cartoon dinosaur Reptar. It is a 3D platform game which requires players to control several of the main characters in order to accomplish the goals through fourteen levels that are accessed when players pick up certain objects and also has bonus levels with Reptar bars. The levels can be played in any order, but the more difficult levels have to be unlocked to be playable. The levels that players explore are mostly based on episodes from the cartoon, such as "Chuckie''s Glasses", and contain various pieces of the Reptar puzzle. The game also has a training and activities mode, as well as a multiplayer mode.' FROM games WHERE igdb_id = 2787 ON CONFLICT (game_id, language_code) DO NOTHING;
