INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The King of Fighters ''98', 'The All-Star dream battle is here at last: It''s King of Fighters ''98! Here come 38 of your favorite characters from the King of Fighters series. Your favorite characters and teams are back! Filled with new surprises like the Roulette Team Edit and Advantage System, King ''98 will pop your cork with unrelenting excitement! The King of Fighters ''98 is the fifth game in The King of Fighters series by SNK.' FROM games WHERE igdb_id = 15429 ON CONFLICT (game_id, language_code) DO NOTHING;
