INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'F-1 World Grand Prix', 'The game consists of five gameplay modes: Grand Prix, a course-by-course simulation of the 1997 season; Exhibition, a single race; Time Trial, a race against the clock and Challenge, which comprised real scenarios from the 1997 season-examples include trying to win the 1997 Hungarian Grand Prix as Damon Hill or beating Jean Alesi as David Coulthard in the 1997 Italian Grand Prix. The final mode allowed 2 players to compete in a single, split-screen race.' FROM games WHERE igdb_id = 3487 ON CONFLICT (game_id, language_code) DO NOTHING;
