INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ehrgeiz', 'Ehrgeiz is a 3D fighting game that features some characters from Final Fantasy VII. Cloud Strife and Tifa Lockhart are playable in the arcade and the PlayStation versions, and Sephiroth, Yuffie Kisaragi, Vincent Valentine and Zack Fair were added to the PlayStation version''s roster. Ehrgeiz differs from most 3D fighting games by drawing heavily from the concepts of wrestling games and Dream Factory''s own Tobal series, which allow for full 360-degree movement and do not require fighters to be facing each other at all times.' FROM games WHERE igdb_id = 1361 ON CONFLICT (game_id, language_code) DO NOTHING;
