INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Dynamite Cop', 'A beat ''em up video game published by Sega and initially released in arcades on Sega Model 2 hardware. It is the sequel to the 1996 game, Dynamite Deka which was released outside Japan as Die Hard Arcade. The game was ported to the Dreamcast and released internationally in 1999, this time without the Die Hard license. A third sequel, Asian Dynamite, was released only in arcades.' FROM games WHERE igdb_id = 36737 ON CONFLICT (game_id, language_code) DO NOTHING;
