INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Ninja: Shadow of Darkness', 'Ninja is a fast-paced, arcade style action-adventure. The game features highly detailed environments, a wide range of special effects and huge end-of-level bosses. Assuming the role of the young ninja Kurosawa, you must guide him through a series of progressively difficult environments. The Ninja is able to collect magic potions, scrolls, extra lives, energy and weapons throughout the levels to help him on his quest.' FROM games WHERE igdb_id = 18941 ON CONFLICT (game_id, language_code) DO NOTHING;
