INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('battlezone', 613, '1998-02-28', 70, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1y0g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/lz3zqhczgzibjjogws38.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Battlezone', 'You are the high-level Commander making decisions from your own war-ravaged tank. Lead your U.S. troops on a mission to gain control of a superior alien technology in the true "space race" against the Soviets.... or cross enemy lines to the Soviet side. It''s all under your command. *Full-Scale 3-D Action: pilot one of 25 anti-gravity war machines, and wield 25 devastating weapons - including mortars, mines, and the Thumper Device which triggers on-the-fly earthquakes on the morphable terrain. * Complete Strategic Control: coordinate full-scale attacks with over 30 unique units, such as tanks, infantry and mobile assault turrets. Call in artillery, deploy wingmen and manage resources - all from within your tank. * Dynamic First-Person Immersion: lose your vehicle in battle, bail out, parachute to safety; then use your sniper rifle to take over another unit. Switch vehicles right on the battlefield of one of seven distinct moons or planets!' FROM games WHERE igdb_id = 613 ON CONFLICT (game_id, language_code) DO NOTHING;
