INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Half-Life', 'Dr. Gordon Freeman doesn''t speak, but he''s got a helluva story to tell. This first-person roller-coaster initiated a new era in the history of action games by combining engrossing gameplay, upgraded graphics, ingenious level design and a revolutionary story that may not be all that it seems, told not through cutscenes, but through the visual environment.' FROM games WHERE igdb_id = 231 ON CONFLICT (game_id, language_code) DO NOTHING;
