INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('microsoft-combat-flight-simulator-wwii-europe-series', 36536, '1998-12-01', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6ck8.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/zkjd0gcds23fzn8ckasf.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Microsoft Combat Flight Simulator: WWII Europe Series', 'Microsoft''s flight simulators aimed realistically portray life as a commercial pilot for over a decade before combat was added. In this offshoot (pardon the pun) of the series, you are a combat pilot during World War II, for either the RAF, USAAF or Luftwaffe. Eight different planes and the battered cities of Berlin, Paris and London are incorporated. Full cockpit designs and damage models are featured - watch for engine smoke and explosion debris. There is a full campaign mode, which takes in the Battle of Britain, defending London during the Blitz, and finishing the job started on D-Day by pummeling ground targets.You can also play individual missions or fly freely. Online multiplayer options allow you to take this worldwide fight around the real world.' FROM games WHERE igdb_id = 36536 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 36536 AND ge.slug = 'simulator' ON CONFLICT DO NOTHING;
