INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('dx-ball-2', 19225, '1998-12-16', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co4omv.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/qfni237iuqpx7u5eygk1.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'DX-Ball 2', 'DX-Ball 2 is a brick buster game for Microsoft Windows, developed by Longbow Games. As a follow up to DX-Ball by Michael P. Welch, the sequel is foremost remarked by the introduction of its 16-bit high-colour engine, presenting textured bricks and background graphics in vivid colours. The game also features two new Power-Ups, an easy to play "Kid-Mode", and a hotseat multiplayer mode, alongside an original soundtrack by SideWinder. DX-Ball 2 also introduces the feature of board-set selection, allowing the player to select between different sets of boards to play. The free demo thereby comes packed with a total of 24 boards divided into 6 board-sets of 4 boards search. Additional board packs can then be installed for more boards, whereas Board Pack 1 will expand the demo board-sets to 25 boards each, for a total of 150 boards. While a total of five board packs were released for the game, DX-Ball 2 was eventually succeeded by Rival Ball in 2001. A 20th Anniversary edition was announced on August 23rd, 2018 and was released on November 21st, 2018, which features a new high resolution boardset,new power ups,online leaderboard and boardset editor.' FROM games WHERE igdb_id = 19225 ON CONFLICT (game_id, language_code) DO NOTHING;
