INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anno-1602-creation-of-a-new-world', 303, '1998-09-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3xv2.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/jrkl8uz7uymlzi1xwsn6.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anno 1602: Creation of a New World', 'It is the year 1602 and you find yourself in command of a sailing vessel, navigating the waters of the uncharted island world of Anker. You have aboard your ship no more than an handful of trusty followers and a limited supply of food and building materials. You are here to begin a new life. As you select which island to settle, your future is already sealed, for each one has its own special characteristics. Your goal is to create a whole new world. Explore, construct, settle, trade and defend - that is the challenge that lies before you! Anno 1602 takes you into the world of construction strategy games. Build a realistic, living world for yourself according to your own ideas; your chosen strategy will decide the development and destiny of your towns and villages. Prove your diplomatic skills in your dealings with natives, your comrades and pirates too. Start by building up farms, plantations and small workshops to produce, then use your business acumen and begin to generate trade with your fellow players. But beware, for with riches and prosperity also comes envy and anger! Train soldiers and build defensive structures to protect your property and wealth, or perhaps it may be wise to put your negotiation skills to use outside of business?' FROM games WHERE igdb_id = 303 ON CONFLICT (game_id, language_code) DO NOTHING;
