INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Vol. 4: The Ride', 'For the fourth volume of the CD-Rom trivia game show, the You Don''t Know Jack crew decided to throw out the YDKJ rule book and start fresh! This ain''t your daddy’s You Don''t Know Jack! Suffice to say, you can take any preconceived notions you''ve had about the series and chuck ''em down an open elevator shaft because volume 4 is going to take you on the ride of your life!' FROM games WHERE igdb_id = 16784 ON CONFLICT (game_id, language_code) DO NOTHING;
