INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Echo Night', 'Echo Night is a mystery adventure video game developed by From Software. The story revolves around Richard Osmond and his journey to find out what happened to the ship Orpheus, which mysteriously disappeared from the sea. The story will uncover too the mystery about two stones which contain some kind of power.' FROM games WHERE igdb_id = 9514 ON CONFLICT (game_id, language_code) DO NOTHING;
