INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('carmageddon-ii-carpocalypse-now', 951, '1998-10-12', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co3si6.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar174y.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Carmageddon II: Carpocalypse Now', 'Max is back!! Bigger and bader than ever before!!!! Stainless/SCi announces the release of the eagerly awaited sequel to its 1997 smash hit Carmageddon, Carmageddon 2 - Carpocalypse now. Carmageddon 1 was released last year amongst "just a tiny bit" of controversy, with calls to "ban this killer car game" from the media around the world, and then went on to prove its critics wrong by scooping a body bag full of awards from around the globe. Developed once again, by the patients of Parkhurst prison''s clinically insane wing, known as Stainless Software, Carmageddon 2 - Carpocalypse Now, is destined to make computer gaming history again. Let''s face it, Carmageddon 1 caused a blood storm in a teacup, this time prepare for a full-on tidal wave. Carmageddon 2 - Carpocalypse Now will take players to the next level of gameplay, whether you are trying to hold down your lunch after taking out those pedestrians waiting for a bus, or franticly trying to re-build your car after having your butt kicked by one of the GAME''S AI opponents, Carmageddon 2 - Carpocalypse Now will take you to the edge and further as you race your way through 1998''s greatest driving game.' FROM games WHERE igdb_id = 951 ON CONFLICT (game_id, language_code) DO NOTHING;
