INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Seven Kingdoms: Ancient Adversaries', 'Seven Kingdoms Ancient Adversaries: This is a strategy game designed by Trevor Chan, the author of Capitalism. Players choose to play as one of seven civilizations. Military might is not enough to win the game. Players must plan actions a few steps ahead, trade with other races, build up industry and establish diplomatic contacts.' FROM games WHERE igdb_id = 33303 ON CONFLICT (game_id, language_code) DO NOTHING;
