INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sky City Blues', 'SKY CITY BLUES is a 3D action shooter. It consists of one  big level that takes place in a flying city - the SKY CITY.  The goal of the game is to find the teleporter that takes you out of the city,  brings back to earth. The guard droids from SKY CITY will try  to prevent this. So go on a search for the teleporter  and turn off the guard droids that get in your way  put.' FROM games WHERE igdb_id = 132824 ON CONFLICT (game_id, language_code) DO NOTHING;
