INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'MechCommander', 'MechCommander is the second real-time tactics (RTT) video game based on FASA''s BattleTech/MechWarrior franchise (though often being called a real-time strategy game), developed by FASA Interactive and distributed by MicroProse. MechCommander was released in 1998. It had an expansion which was later combined with the original title and released as MechCommander Gold. A sequel also exists (distributed by Microsoft)—MechCommander 2. MicroProse also used many of the ideas in their 2000 Starship Troopers game.' FROM games WHERE igdb_id = 19193 ON CONFLICT (game_id, language_code) DO NOTHING;
