INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Alurwe: Ein Spaziergang durch Alt-Urfahr West', 'Old Urfahr West (Alurwe) is a very old district of Linz / Danube. Alturfahr has its own character. From old to old, not very old or modern, houses and squares, streets and alleys, shops and restaurants are all present. The people are friendly, children can still play on the street, everywhere dogs and cats are encountered. (Strangely many cats?) Feel the peculiar flair of Urfahr by playing ALURWE.' FROM games WHERE igdb_id = 117423 ON CONFLICT (game_id, language_code) DO NOTHING;
