INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Railroad Tycoon II', 'Sid Meier''s Railroad Tycoon is a business simulation game. Railroad Tycoon was written by game designer Sid Meier and published by MicroProse Railroad Tycoon 2 is the only game of the series that was released fr the PSX console. You try to make it to the top of the transportation industry in Railroad Tycoon II, a simulation that takes you from a wannabe to a tycoon (if your lucky!).' FROM games WHERE igdb_id = 285 ON CONFLICT (game_id, language_code) DO NOTHING;
