INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anna Kournikova''s Smash Court Tennis', 'Anna Kournikova''s Smash Court Tennis is a tennis video game featuring the likeness of professional tennis player Anna Kournikova. The game features two practice modes, tournaments and exhibition matches. Winning in tournaments rewards world ranking points which unlock new characters to use, each with different attributes and skills and extra items to use.' FROM games WHERE igdb_id = 18666 ON CONFLICT (game_id, language_code) DO NOTHING;
