INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Brány Skeldalu', 'Gates of Skeldal is a dungeon crawler with a rather unique graphical style and originally only released for the Czech market. The game has never been officially released in English but has been translated by fans as a result of crowd-funding. Now it is available on both Android and iOS. The game was originally released with map editor enabling players to create their own dungeons and maps.' FROM games WHERE igdb_id = 19791 ON CONFLICT (game_id, language_code) DO NOTHING;
