INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Fifth Element', 'The Fifth Element is a third-person adventure wherein you take on the persona of one of two characters. Your two choices stem from the two main ones from the movie, Korben Dallas or Leeloo Minai Lekatariba-Lamina-Tchai Ekbat. Korben, played by Bruce Willis in the film, is a cab driver. He lives in New York City when the game starts, and he is the one man capable of saving the world. Leeloo is The Fifth Element. She is the only hope that the universe has against Pure Evil.' FROM games WHERE igdb_id = 50805 ON CONFLICT (game_id, language_code) DO NOTHING;
