INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'You Don''t Know Jack Headrush', 'Forget everything you know about a You Don''t Know Jack game because YDKJ’s horribly deformed, mutant offspring Headrush has been birthed! Twisted animation, insane question types, and a bizarre appetite for all human excretory fluids and gassed add up to the most over-the-top YDKJ game ever! Fire this game up and stand back, because this is not your Mommy and Daddy’s ''You Don''t Know Jack''!' FROM games WHERE igdb_id = 16788 ON CONFLICT (game_id, language_code) DO NOTHING;
