INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Major League Baseball Featuring Ken Griffey Jr.', 'Make your dreams of becoming a Major Leaguer a reality! Hit a grand slam, pitch a no-hitter, go for the cycle and steal home - all in the same game! If that''s not enough, check out the real-time stat tracking in over 30 major categories. Improve your team by making the right trades and picking up the best free agents. Major League Baseball Featuring Ken Griffey Jr. is so real, every pitch counts!' FROM games WHERE igdb_id = 3540 ON CONFLICT (game_id, language_code) DO NOTHING;
