INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('quest-for-glory-v-dragon-fire', 1897, '1998-12-07', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co21fr.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc8ux8.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Quest for Glory V: Dragon Fire', 'After having survived the dangers he encountered on his previous journey, the hero travels with the wizard Erasmus to a Greece-like country called Silmaria. Its king was recently murdered, and, according to the land''s traditions, the crown will be given to the one who passes a contest known as the Rites of Rulership. The hero enters the contest, aided by Erasmus, Rakeesh, and other old friends. However, as the competition progresses, contestants are being systematically killed by an unknown assassin. All the victims are murdered near the Dragon Pillars, which keep the Dragon of Silmaria in captivity. The hero must investigate the crimes and save Silmaria from a grave danger. Dragon Fire is the final game in the Quest for Glory series. Like the previous games in the series, Dragon Fire is a hybrid between puzzle-solving adventure and role-playing game. The player talks to the world''s inhabitants, gathering clues and items necessary to acquire in order to complete the quests and advance the story. Unlike all its predecessors, Dragon Fire has no separate battle screens; the action-based battles take place on the exploration screen, utilizing a simple point-and-click interface, similarly to Diablo. The game has heavier weapon and armor management than other Quest for Glory games, strengthening the RPG angle. Many quests are optional or can be completed in different ways. The hero can also marry one of the several major female characters in the game, provided the player does the right thing to impress the girl.' FROM games WHERE igdb_id = 1897 ON CONFLICT (game_id, language_code) DO NOTHING;
