INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grand Prix Legends', 'Grand Prix Legends (nicknamed GPL) is a computer racing simulator developed by Papyrus Design Group and published in 1998 by Sierra Entertainment. At the time of its release, it simulated the 1967 Formula One season and is considered to be one of the most realistic racing games ever released.' FROM games WHERE igdb_id = 729 ON CONFLICT (game_id, language_code) DO NOTHING;
