INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Virtual Pool 64', 'The ultra-real physics make Virtual Pool 64 as close to real pool as it gets! Choose from 9 types of pool including favorites like 9-Ball, Straight Pool, 8-Ball and One Pocket. Three levels of difficulty: Amateur, Professional and Championship. Master trick shots, learn a new game or challenge hundreds of computer opponents in exciting tournament play.' FROM games WHERE igdb_id = 3624 ON CONFLICT (game_id, language_code) DO NOTHING;
