INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The X-Files: Unrestricted Access', 'As an extension of one of the most long-running television series of all time, The X-Files, play through the eyes of Special Agent Craig Willmore, a new FBI field investigator brought in to locate missing agents Fox Mulder and Dana Scully whose last location was the Everett, Washington, area. In this "movie quality" video production, characters are played by the actors and actresses from the show, including Gillian Anderson (Scully) and David Duchovny (Mulder).' FROM games WHERE igdb_id = 64238 ON CONFLICT (game_id, language_code) DO NOTHING;
