INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Laura''s Happy Adventures', 'Laura''s Happy Adventures is an adventure video game developed by Ubi Soft Montreal and published by Ubi Soft Entertainment, and released as part of the Playmobil Interactive series of products. The game was originally released in 1998, becoming the first adventure video game to be produced primarily for young girls as a target audience. The setting was based on Playmobil''s Victorian dollhouse line. The game''s storyline revolved around a good-natured young girl named Laura as she solved the mystery of a magic diamond by helping the people around her, both within her family and the outside villagers, blending real-world everyday life with fantasy elements.' FROM games WHERE igdb_id = 66703 ON CONFLICT (game_id, language_code) DO NOTHING;
