INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('colony-wars-vengeance', 8281, '1998-10-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co23s7.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmers.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Colony Wars: Vengeance', 'After the first Colony Wars game, the Earth Empire was defeated... and the remnants of this regime sealed inside of the Sol System, cut off from the rest of the galaxy by some unknown technology. Within Sol, the Earth Empire civilization has fallen apart. Various tribes and factions, warring with one another have left the once great home system of humanity a wreck of salvage and waste from used up resources. One leader however, a Commander Kron, seeks to unite the warring clans under a banner of vengeance... and together find some way to break out from this solar prison. The game is space combat, done from a cockpit view. Different combinations of weapons can be equipped on your space fighter prior to launch. Missions take place in space as well as inside planet atmospheres. Various buttons cycle weapons, activate tractor beams, communicate responses and navigate your ship. In typical space combat fashion, you are equipped with 360 degrees of movement as well as thrust and braking options. The game does not feature realistic inertia and objects will gradually "slow" in space.' FROM games WHERE igdb_id = 8281 ON CONFLICT (game_id, language_code) DO NOTHING;
