INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'International Superstar Soccer ''98', 'Do you have what it takes to be a superstar? Over 17,000 new motion captured animations! Team motivation, players and teams react to real game situations. Vertical camera angle allows you to see more of the pitch. 52 International teams and 9 unique soccer stadiums. Create your own players and trade existing ones. Infinite team formations and customizable strategies.' FROM games WHERE igdb_id = 3514 ON CONFLICT (game_id, language_code) DO NOTHING;
