INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'WCW/nWo Thunder', 'Feel the power. Take control of the world''s greatest athletes in WCW/NWO Thunder! Dictate the rules, then break them. Only your imagination can keep you from ruling the world of professional wrestling! Over 60 WCW and NWO Superstars, including Goldberg, Hollywood Hogan, Kevin Nash, Diamond Dallas Page, The Giant, Bret Hart, Konnan, Rowdy Roddy Piper, Curt Henning, Saturn, Randy Savage, Chris Jericho, Sting, Raven, and more! Full-Screen Wrestler entrances with theme music Commentary from Thunder announcers Tony Schiavone & Mike Tenay' FROM games WHERE igdb_id = 18315 ON CONFLICT (game_id, language_code) DO NOTHING;
