INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Future Cop: LAPD', 'Crime War is a story mode, following a day in the life of an LAPD X1-Alpha pilot. The story events range from rogue lunatics arming observatories with weapons, to a malfunctioning supercomputer. Players begin in a futuristic Griffith Park, but as they advance through the game they may unlock areas such as Venice Beach, LAX and Long Beach.' FROM games WHERE igdb_id = 11235 ON CONFLICT (game_id, language_code) DO NOTHING;
