INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'All Star Tennis ''99', 'Play as 8 world class ATP / WTA tour players (including Mark Philippoussis, Richard Krajicek, Conchita Martinez & Jana Novotna) as well as 4 fictional players through a range of tournaments on grass, clay, hard court and rebound ace surfaces. Lob, volley, smash and serve past computer controlled players in singles or doubles, 4 player multiplayer doubles, and 8 player multiplayer singles and doubles tournaments.' FROM games WHERE igdb_id = 3436 ON CONFLICT (game_id, language_code) DO NOTHING;
