INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'NASCAR 99', 'NASCAR 99, the arcade-style racing game from EA and Stormfront Studios. In addition to 2-player simultaneous racing the game featured 37 officially licensed cars and 17 tracks, as well as the voices of Bob Jenkins and Benny Parsons commentary. Using the Andretti Racing engine, NASCAR 99 was EAs first entry into NASCAR racing for the Nintendo 64 and and Playstation.' FROM games WHERE igdb_id = 3547 ON CONFLICT (game_id, language_code) DO NOTHING;
