INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gauntlet Legends', 'Gauntlet Legends is an arcade game released in 1998 by Atari Games. It is a fantasy themed hack and slash styled dungeon crawl game, a sequel to 1985''s popular Gauntlet and 1986''s Gauntlet II and marks the final game in the series to be produced by Atari Games. Its unusual features for an arcade game included passwords and characters that could be saved, enabling players to play over the course of a long period.' FROM games WHERE igdb_id = 3501 ON CONFLICT (game_id, language_code) DO NOTHING;
