INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('pro-pinball-big-race-usa', 838, '1998-12-31', 87, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co1pi0.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/arueg.jpg', NOW()) ON CONFLICT DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Pro Pinball: Big Race USA', 'A whirlwind frenzy of color, sound, and adrenaline-pumping action. Take an exciting ride across the USA for your chance to compete in the big race and win hoards of cash. But watch out for the police car on your tail. Packed with more features than your local multiplex, Big Race USA brings a whole new dimension of mind-boggling realism to your PlayStation. If you''ve always wanted a pinball machine but just didn''t have the money, you''ll be delighted at the real-life pinball physics now available on the PlayStation. The PRO PINBALL series strikes again, this time with an auto-themed trek across the country. All of the realistic touches of arcade pinball are present from the bumpers right down to the click of the flippers. You can adjust the camera three different ways to view the table from any angle you desire, and you can even take a gander at a pre-game slideshow that details the table''s layout. It''s easy to change the table rules, switch the screen position, tweak the graphics and sound, and choose a difficulty level: Extra Easy, Easy, Medium, Hard, or Extra Hard. There''s also a custom difficulty level that allows you to adjust any of the game''s settings to provide extra challenges or assistance for yourself. Add in magnetic ball saving, multiball, and other bonuses and you''ve got yourself one heck of a cross-country journey. Pinball wizards and videogamers alike will revel in the thorough attention to detail and creativity in PRO PINBALL: Big Race USA.' FROM games WHERE igdb_id = 838 ON CONFLICT (game_id, language_code) DO NOTHING;
